// Reject malformed callbacks early, with a message that says what is missing.
const input = $input.first().json;
const body = input.body ?? {};
const query = input.query ?? {};

const eventType = body.eventType;
const apifyRunId = body.resource?.id ?? body.eventData?.actorRunId;
const datasetId = body.resource?.defaultDatasetId;
const runId = query.runId;

const missing = [];
if (!eventType) missing.push('eventType');
if (!apifyRunId) missing.push('resource.id');
if (!runId) missing.push('query.runId');
if (eventType === 'ACTOR.RUN.SUCCEEDED' && !datasetId) missing.push('resource.defaultDatasetId');

if (missing.length) {
  // Thrown errors stop the run and reach the global error workflow.
  throw new Error(`Invalid Apify callback, missing: ${missing.join(', ')}`);
}

return [{
  json: {
    eventType,
    apifyRunId,
    datasetId,
    runId,
    statusMessage: body.resource?.statusMessage ?? null,
  },
}];

// Apify can deliver the same webhook more than once.
// Skip a run that was already dispatched so the worker never processes it twice.
// Static data persists for production (active) executions only;
// at higher volume, replace this with a UNIQUE key in Postgres.
const store = $getWorkflowStaticData('global');
store.seenRuns = store.seenRuns ?? [];

const payload = $input.first().json;
if (store.seenRuns.includes(payload.apifyRunId)) {
  return [];
}

store.seenRuns.push(payload.apifyRunId);
store.seenRuns = store.seenRuns.slice(-500);
return [{ json: payload }];

const { runId } = $('✅ Code - Validate Payload').first().json;
const BATCH_SIZE = 50;

const resolveLocation = (loc) => {
  if (!loc) return '';
  if (typeof loc === 'string') return loc;
  return loc.linkedinText || loc?.parsed?.text || '';
};

// Full response = exactly one item on success, even for an empty dataset,
// and no item at all on this branch when the request fails.
const response = $input.first()?.json ?? {};
const rawItems = Array.isArray(response.body) ? response.body : [];

const cleaned = rawItems
  .filter((p) => p?.firstName || p?.linkedinUrl)
  .map((p) => {
    const currentExp = (p.experience || []).find((e) => e.endDate?.text === 'Present')
      || (p.experience || [])[0] || {};
    const currentPos = (p.currentPosition || []).find((x) => x.dateRange?.end === null)
      || (p.currentPosition || [])[0] || {};

    return {
      fullName: `${p.firstName || ''} ${p.lastName || ''}`.trim(),
      firstName: p.firstName || '',
      lastName: p.lastName || '',
      currentTitle: currentExp.position || p.headline || '',
      currentCompany: currentExp.companyName || currentPos.companyName || '',
      companyLinkedinUrl: currentExp.companyLinkedinUrl || currentPos.companyLinkedinUrl || '',
      profileLinkedinUrl: p.linkedinUrl || '',
      linkedinSummary: p.about || p.summary || '',
      location: resolveLocation(p.location),
    };
  })
  .filter((p) => p.fullName);

const batches = [];
for (let i = 0; i < cleaned.length; i += BATCH_SIZE) {
  batches.push(cleaned.slice(i, i + BATCH_SIZE));
}

// Always emit at least one item: an empty dataset must still be reported to the backend.
if (batches.length === 0) {
  return [{ json: { runId, profiles: [], profiles_found: 0, batchIndex: 0, batchCount: 0 } }];
}

return batches.map((profiles, batchIndex) => ({
  json: {
    runId,
    profiles,
    profiles_found: cleaned.length,
    batchIndex,
    batchCount: batches.length,
  },
}));

// One summary for every failure path: failed Apify run, dataset fetch, worker trigger, progress report.
const validated = $('✅ Code - Validate Payload').first().json;

const reasons = $input.all().map(({ json }) => {
  if (typeof json.error === 'string') return json.error;
  if (json.error?.message) return json.error.message;
  if (json.eventType && json.eventType !== 'ACTOR.RUN.SUCCEEDED') {
    return `Apify run ended with ${json.eventType}${json.statusMessage ? `: ${json.statusMessage}` : ''}`;
  }
  return 'Unknown error';
});

return [{
  json: {
    runId: validated.runId,
    apifyRunId: validated.apifyRunId,
    stage: $prevNode.name,
    reason: [...new Set(reasons)].slice(0, 3).join(' | '),
    failedItems: reasons.length,
    executionId: $execution.id,
  },
}];

